using System;
using PoEController.Menus;
using UnityEngine;

namespace PoEController.Input
{
    public enum InputDevice
    {
        KeyboardMouse,
        Gamepad,
    }

    /// <summary>
    /// Tracks which device the player last used so UI, cursor and prompts can switch on the fly. Mouse activity
    /// generated by menu navigation (MouseEmulator) is ignored.
    /// </summary>
    public sealed class InputModeTracker
    {
        private const float MouseMoveThresholdPixels = 6f;
        private const float SyntheticPositionTolerance = 2f;
        // Mouse/keyboard input arriving while the pad is in use is ignored for this long. Steam Input (when enabled
        // for the game) turns pad presses into keys and stick motion into mouse moves; without this the mode would
        // flip back and forth on every press.
        private const float PadGraceSeconds = 0.3f;

        private Vector3 m_LastMouse;
        private float m_LastPadActivity = float.NegativeInfinity;

        public InputDevice Active { get; private set; } = InputDevice.KeyboardMouse;

        public event Action<InputDevice> Changed;

        public void Update(Gamepad pad)
        {
            Vector3 mouse = UnityEngine.Input.mousePosition;
            bool mouseMoved = (mouse - m_LastMouse).sqrMagnitude > MouseMoveThresholdPixels * MouseMoveThresholdPixels
                && ((Vector2)mouse - MouseEmulator.LastSetPosition).sqrMagnitude > SyntheticPositionTolerance * SyntheticPositionTolerance;
            m_LastMouse = mouse;

            bool synthetic = MouseEmulator.IsSyntheticActivity;
            if (pad.AnyActivity)
            {
                m_LastPadActivity = Time.unscaledTime;
                Set(InputDevice.Gamepad);
            }
            else if (Time.unscaledTime - m_LastPadActivity < PadGraceSeconds)
            {
                // Still the pad's turn; see PadGraceSeconds.
            }
            else if (mouseMoved
                || KeyboardOrMouseButtonDown(ignoreMouseButtons: synthetic)
                || (!synthetic && UnityEngine.Input.mouseScrollDelta != Vector2.zero))
            {
                Set(InputDevice.KeyboardMouse);
            }
        }

        public void Set(InputDevice device)
        {
            if (device == Active)
            {
                return;
            }
            Active = device;
            Changed?.Invoke(device);
        }

        private static bool KeyboardOrMouseButtonDown(bool ignoreMouseButtons)
        {
            if (!UnityEngine.Input.anyKeyDown)
            {
                return false;
            }
            // Unity's legacy input reports controller buttons as JoystickButton keys; those must not count.
            for (KeyCode k = KeyCode.JoystickButton0; k <= KeyCode.Joystick8Button19; k++)
            {
                if (UnityEngine.Input.GetKeyDown(k))
                {
                    return false;
                }
            }
            if (ignoreMouseButtons)
            {
                bool anyMouse = false;
                for (int b = 0; b < 7; b++)
                {
                    anyMouse |= UnityEngine.Input.GetMouseButtonDown(b);
                }
                // anyKeyDown was caused only by our own clicks.
                if (anyMouse)
                {
                    return false;
                }
            }
            return !OnlySystemKeys();
        }

        /// <summary>
        /// Keys that never mean "playing with the keyboard" (0.39.x: Win + Alt + PrtScn for a screenshot switched
        /// the screen to the keyboard UI): Alt, the Windows key, Print Screen / SysRq, F12 (Steam's screenshot key) and
        /// Tab while Alt is held (Alt-Tab). True when nothing else went down this frame.
        /// </summary>
        private static bool OnlySystemKeys()
        {
            bool alt = UnityEngine.Input.GetKey(KeyCode.LeftAlt) || UnityEngine.Input.GetKey(KeyCode.RightAlt) || UnityEngine.Input.GetKey(KeyCode.AltGr);
            KeyCode[] keys = AllKeys;
            for (int i = 0; i < keys.Length; i++)
            {
                KeyCode k = keys[i];
                if (k >= KeyCode.Mouse0 || !UnityEngine.Input.GetKeyDown(k))
                {
                    continue;
                }
                switch (k)
                {
                    case KeyCode.LeftAlt:
                    case KeyCode.RightAlt:
                    case KeyCode.AltGr:
                    case KeyCode.LeftWindows:
                    case KeyCode.RightWindows:
                    case KeyCode.LeftApple:
                    case KeyCode.RightApple:
                    case KeyCode.Print:
                    case KeyCode.SysReq:
                    case KeyCode.F12:
                        continue;
                    case KeyCode.Tab:
                        if (alt)
                        {
                            continue;
                        }
                        return false;
                    default:
                        return false;
                }
            }
            // Mouse buttons are KeyCodes too (Mouse0 and up): a real click still counts.
            for (int b = 0; b < 7; b++)
            {
                if (UnityEngine.Input.GetMouseButtonDown(b))
                {
                    return false;
                }
            }
            return true;
        }

        private static KeyCode[] s_AllKeys;

        private static KeyCode[] AllKeys => s_AllKeys ?? (s_AllKeys = (KeyCode[])System.Enum.GetValues(typeof(KeyCode)));
    }
}
